          "key": "method",
          "title": "B9 bulk import model",
          "rows": [
            {
              "label": "Operation",
              "value": "Create All Screens is one user-facing bulk import operation; manual per-screen import is not implemented.",
              "refs": []
            },
            {
              "label": "Source-derived",
              "value": "Inventory is derived from routes, SCREENS, governed M06, governed M08, shell/component/pattern sources and B1-B8 tokens.",
              "refs": []
            },
            {
              "label": "Idempotency",
              "value": "Repeated runs use deterministic identity, signatures and placement; conflicts stop rather than silently overwrite.",
              "refs": []
            },
            {
              "label": "Arithmetic",
              "value": "142 content route files - 2 internal design references - 12 workforce host routes - 1 quote host route - 1 app agent-profile host route + 35 M06 registered screens + 10 M08 registered screens + 6 quote UX state frames + 2 source-backed visual-state frames = 179",
              "refs": []
            }
          ]
